const { spawnSync } = require('child_process');
const BIN = '/workspace/dataset/test4_executable';

// run(valueBuffer) -> {code, out(hex), err(text)}
function run(val) {
  const r = spawnSync(BIN, ['--a', val], { encoding: 'buffer', maxBuffer: 1 << 28 });
  return {
    code: r.status,
    signal: r.signal,
    outHex: r.stdout ? r.stdout.toString('hex') : '',
    outLen: r.stdout ? r.stdout.length : 0,
    err: r.stderr ? r.stderr.toString('utf8') : '',
    error: r.error ? String(r.error) : null,
  };
}
module.exports = { run, BIN };

const { run } = require('/tmp/probe-degenerate/drv.js');

// ---- Q1: fallback length independence
const cases = [];
for (const n of [1,2,3,5,17,100,1000]) {
  cases.push(['homog "!" x'+n, '!'.repeat(n)]);
  cases.push(['homog " " x'+n, ' '.repeat(n)]);
}
const mixedPool = '! .,;:?@#$%^&*()[]{}<>|/~`+=\'"\t\n\r\v\f';
for (const n of [1,2,3,5,17,100,1000]) {
  let s = '';
  for (let i=0;i<n;i++) s += mixedPool[i % mixedPool.length];
  cases.push(['mixed x'+n, s]);
}
cases.push(['empty', '']);

for (const [label, v] of cases) {
  const r = run(v);
  console.log(JSON.stringify({label, len: v.length, code: r.code, outHex: r.outHex, err: r.err.slice(0,120)}));
}

const { run } = require('/tmp/probe-degenerate/drv.js');
// every single ASCII char 0x01..0x7f alone, plus 0x00 attempt
const rows = [];
for (let c = 1; c <= 0x7f; c++) {
  const v = String.fromCharCode(c);
  const r = run(v);
  rows.push({byte:'0x'+c.toString(16).padStart(2,'0'), code:r.code, outHex:r.outHex, err:r.err.replace(/\n/g,'\\n').slice(0,150)});
}
for (const row of rows) console.log(JSON.stringify(row));

